const b = $json.body ?? {};
const secret = $json.headers?.['x-axio-secret'];
if (!$env.AXIO_WEBHOOK_SECRET) throw new Error('AXIO_WEBHOOK_SECRET is not configured');
if (secret !== $env.AXIO_WEBHOOK_SECRET) throw new Error('Unauthorized');
const allowed = new Set(['idea', 'active', 'paused', 'shipped']);
if (!/^[a-z0-9-]{2,80}$/.test(b.projectId ?? '')) throw new Error('projectId: lowercase letters, numbers, hyphens only');
if (!Number.isInteger(b.progress) || b.progress < 0 || b.progress > 100) throw new Error('progress must be an integer from 0 to 100');
if (!allowed.has(b.status)) throw new Error('status must be idea, active, paused, or shipped');
for (const key of ['next', 'note']) if (typeof b[key] !== 'string' || b[key].length > 500) throw new Error(`${key} is required and must be at most 500 chars`);
if (!Array.isArray(b.tags) || b.tags.length > 8 || b.tags.some(x => typeof x !== 'string' || x.length > 40)) throw new Error('tags must be an array of up to 8 short strings');
const safe = { projectId:b.projectId, title:typeof b.title === 'string' ? b.title.slice(0,100) : undefined, status:b.status, progress:b.progress, next:b.next, note:b.note, tags:b.tags };
return [{ json: { payloadB64: Buffer.from(JSON.stringify(safe)).toString('base64url'), accepted: safe } }];
